CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, root_path TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS repositories (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL UNIQUE REFERENCES workspaces(id), canonical_path TEXT NOT NULL, common_git_dir TEXT NOT NULL, base_ref TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_bindings (id TEXT PRIMARY KEY, provider_name TEXT NOT NULL, package_version TEXT NOT NULL, config_revision INTEGER NOT NULL, capabilities TEXT NOT NULL, credential_refs TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS roles (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), name TEXT NOT NULL CHECK(name IN ('lead','developer-a','developer-b','reviewer')), kind TEXT NOT NULL CHECK(kind IN ('dsh-lead','subagent')), provider_binding_id TEXT REFERENCES provider_bindings(id), prompt TEXT NOT NULL, revision INTEGER NOT NULL, UNIQUE(workspace_id,name), CHECK((name='lead' AND kind='dsh-lead' AND provider_binding_id IS NULL) OR (name<>'lead' AND kind='subagent' AND provider_binding_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS workflows (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), goal TEXT NOT NULL, lead_session_id TEXT, plan_revision INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, integration_ref TEXT NOT NULL, base_commit TEXT NOT NULL, summary TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_workflow ON workflows((1)) WHERE status NOT IN ('completed','failed','cancelled');
CREATE TABLE IF NOT EXISTS tasks (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id), role_id TEXT REFERENCES roles(id), kind TEXT NOT NULL CHECK(kind IN ('change','analysis')), title TEXT NOT NULL, instructions TEXT NOT NULL, expected_paths TEXT NOT NULL, acceptance_criteria TEXT NOT NULL, status TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 0, accepted_commit TEXT, source_head TEXT, blocking_reason TEXT);
CREATE TABLE IF NOT EXISTS task_dependencies (task_id TEXT NOT NULL REFERENCES tasks(id), depends_on_task_id TEXT NOT NULL REFERENCES tasks(id), PRIMARY KEY(task_id,depends_on_task_id), CHECK(task_id<>depends_on_task_id));
CREATE TRIGGER IF NOT EXISTS dependencies_same_workflow BEFORE INSERT ON task_dependencies WHEN (SELECT workflow_id FROM tasks WHERE id=NEW.task_id)<>(SELECT workflow_id FROM tasks WHERE id=NEW.depends_on_task_id) BEGIN SELECT RAISE(ABORT,'cross-workflow dependency'); END;
CREATE TRIGGER IF NOT EXISTS task_role_workspace BEFORE INSERT ON tasks WHEN NEW.role_id IS NOT NULL AND (SELECT workspace_id FROM roles WHERE id=NEW.role_id)<>(SELECT workspace_id FROM workflows WHERE id=NEW.workflow_id) BEGIN SELECT RAISE(ABORT,'cross-workspace role'); END;
CREATE TABLE IF NOT EXISTS runs (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), role_id TEXT NOT NULL REFERENCES roles(id), purpose TEXT NOT NULL CHECK(purpose IN ('develop','repair','review')), task_attempt INTEGER NOT NULL, status TEXT NOT NULL, provider_snapshot TEXT NOT NULL, dsh_child_id TEXT, dsh_run_id TEXT, stop_reason TEXT, cleanup_status TEXT NOT NULL DEFAULT 'pending', slot_released_at TEXT, deadline TEXT NOT NULL, result TEXT, created_at TEXT NOT NULL, started_at TEXT, ended_at TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_reserved_run_per_task ON runs(task_id) WHERE slot_released_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS one_reserved_run_per_role ON runs(role_id) WHERE slot_released_at IS NULL;
CREATE TRIGGER IF NOT EXISTS run_role_workspace BEFORE INSERT ON runs WHEN (SELECT workspace_id FROM roles WHERE id=NEW.role_id)<>(SELECT w.workspace_id FROM tasks t JOIN workflows w ON w.id=t.workflow_id WHERE t.id=NEW.task_id) BEGIN SELECT RAISE(ABORT,'cross-workspace run'); END;
CREATE TRIGGER IF NOT EXISTS run_global_capacity BEFORE INSERT ON runs WHEN NEW.slot_released_at IS NULL AND ((SELECT count(*) FROM runs WHERE slot_released_at IS NULL)>=3 OR (NEW.purpose='review' AND (SELECT count(*) FROM runs WHERE slot_released_at IS NULL AND purpose='review')>=1) OR (NEW.purpose<>'review' AND (SELECT count(*) FROM runs WHERE slot_released_at IS NULL AND purpose<>'review')>=2)) BEGIN SELECT RAISE(ABORT,'capacity exceeded'); END;
CREATE TABLE IF NOT EXISTS worktrees (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), attempt INTEGER NOT NULL, kind TEXT NOT NULL, path TEXT NOT NULL UNIQUE, branch TEXT, base_commit TEXT NOT NULL, head_commit TEXT, writer_run_id TEXT UNIQUE REFERENCES runs(id), status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS integrations (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id), source_head TEXT NOT NULL, expected_target_head TEXT, candidate_head TEXT, check_ids TEXT NOT NULL DEFAULT '[]', review_run_id TEXT REFERENCES runs(id), status TEXT NOT NULL, candidate TEXT, error TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_integration ON integrations((1)) WHERE status IN ('preparing','reviewing','publishing','cleanup_unknown');
CREATE TABLE IF NOT EXISTS artifacts (id TEXT PRIMARY KEY, run_id TEXT REFERENCES runs(id), type TEXT NOT NULL, relative_path TEXT NOT NULL, sha256 TEXT NOT NULL, byte_size INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS operations (id TEXT PRIMARY KEY, kind TEXT NOT NULL, dedupe_key TEXT NOT NULL UNIQUE, entity_id TEXT NOT NULL REFERENCES tasks(id), phase TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_pending_request ON operations(kind,entity_id) WHERE phase IN ('queued','started');
CREATE TABLE IF NOT EXISTS task_events (event_seq INTEGER PRIMARY KEY AUTOINCREMENT, workflow_id TEXT NOT NULL REFERENCES workflows(id), task_id TEXT REFERENCES tasks(id), run_id TEXT REFERENCES runs(id), request_id TEXT REFERENCES operations(id), type TEXT NOT NULL, payload TEXT NOT NULL, occurred_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_migrations(version,applied_at) VALUES(1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
